import React, { useState, useEffect } from "react";
import { fetchStructDataWithFilters } from "../api/fetch_records";

// Парсер DMS "12°12′12″"
const parseDMS = (dms) => {
  const re = /(\d+)°(\d+)′(\d+)″/;
  const m = dms.match(re);
  return m ? { deg: m[1], min: m[2], sec: m[3] } : { deg: "", min: "", sec: "" };
};

const EditableWaterReport = () => {
  // Данные организации
  const [org, setOrg] = useState({
    organisation_name: "",
    postal_address: "",
    inn: "",
    legal_form: "",
    district: "",
    region: ""
  });

  // Массив записей точек, каждый элемент имеет поля rec.* и month1..3
  const [records, setRecords] = useState([]);

  useEffect(() => {
    (async () => {
      // 1. Организация
      const stored = JSON.parse(localStorage.getItem("org") || "{}");
      setOrg({
        organisation_name: stored.organisation_name || "",
        postal_address: stored.postal_address || "",
        inn: stored.inn || "",
        legal_form: stored.legal_form || "",
        district: stored.district || "",
        region: stored.region || ""
      });

      if (!stored.id) {
        console.error("org.id не найден");
        return;
      }

      // 2. Запрос
      const resp = await fetchStructDataWithFilters("get_struct31", { org_id: stored.id });
      if (!resp || resp.status !== "success") {
        console.error("Ошибка API:", resp?.message);
        return;
      }

      // 3. Заполняем массив records, добавляя editable поля month1..3
      const arr = resp.data.map(rec => ({
        ...rec,
        month1: "",
        month2: "",
        month3: ""
      }));
      setRecords(arr);
    })();
  }, []);

  // Обработчик для month полей в любой строке
  const handleMonthChange = (idx, field, value) => {
    setRecords(rs =>
      rs.map((r, i) =>
        i === idx ? { ...r, [field]: value } : r
      )
    );
  };

  return (
    <div className="water-report">

      {/* === ПЕРВАЯ ТАБЛИЦА: инфо по организации === */}
      <table className="info-table">
        <tbody>
          <tr>
            <td>Наименование организации</td>
            <td colSpan="3">
              <input value={org.organisation_name} readOnly/>
            </td>
          </tr>
          <tr>
            <td>Почтовый адрес</td>
            <td colSpan="3">
              <input value={org.postal_address} readOnly/>
            </td>
          </tr>
          <tr>
            <td>ИНН</td>
            <td><input value={org.inn} readOnly/></td>
            <td>ОПФ</td>
            <td><input value={org.legal_form} readOnly/></td>
          </tr>
          <tr>
            <td>Бассейновый округ</td>
            <td><input value={org.district} readOnly/></td>
            <td>Регион</td>
            <td><input value={org.region} readOnly/></td>
          </tr>
        </tbody>
      </table>

      {/* === ВТОРАЯ ТАБЛИЦА: список точек === */}
      <table className="data-table">
        <thead>
          <tr>
            <th>Объект</th>
            <th>Код типа</th>
            <th>Код объекта</th>
            <th>Категория</th>
            <th>№ точки</th>
            <th colSpan="3">Широта (DMS)</th>
            <th colSpan="3">Долгота (DMS)</th>
            <th>Допустимо, тыс.м³</th>
            <th>Фактически, тыс.м³</th>
            <th>1 мес.</th>
            <th>2 мес.</th>
            <th>3 мес.</th>
          </tr>
        </thead>
        <tbody>
          {records.length === 0 && (
            <tr>
              <td colSpan="16" style={{ textAlign: "center" }}>
                Нет данных
              </td>
            </tr>
          )}

          {records.map((rec, idx) => {
            // Берём DMS из строки "12°12′12″ с.ш., 12°12′12″ в.д."
            const [latPart, lonPart] = (rec.latitude_longitude || "").split(",");
            const lat = parseDMS(latPart);
            const lon = parseDMS(lonPart);

            // Первое разрешение (если есть)
            const perm = Array.isArray(rec.permissions) && rec.permissions.length
              ? rec.permissions[0]
              : {};

            // Последний прибор
            const meter = rec.last_meter || {};

            // Водный объект
            const w = rec.water_object || {};
            const typeCode = w.code_type?.code_value || "";
            const objCode  = w.code_object?.code_value || "";
            const category = w.category || "";

            return (
              <tr key={rec.id}>
                <td><input value={w.name || objCode} readOnly /></td>
                <td><input value={typeCode} readOnly /></td>
                <td><input value={objCode} readOnly /></td>
                <td><input value={category} readOnly /></td>
                <td><input value={rec.id} readOnly /></td>

                <td><input value={lat.deg} readOnly /></td>
                <td><input value={lat.min} readOnly /></td>
                <td><input value={lat.sec} readOnly /></td>
                <td><input value={lon.deg} readOnly /></td>
                <td><input value={lon.min} readOnly /></td>
                <td><input value={lon.sec} readOnly /></td>

                <td><input value={perm.allowed_volume ?? ""} readOnly /></td>
                <td><input value={perm.actual_volume ?? ""} readOnly /></td>

                <td>
                  <input
                    name="month1"
                    value={rec.month1}
                    onChange={e => handleMonthChange(idx, "month1", e.target.value)}
                  />
                </td>
                <td>
                  <input
                    name="month2"
                    value={rec.month2}
                    onChange={e => handleMonthChange(idx, "month2", e.target.value)}
                  />
                </td>
                <td>
                  <input
                    name="month3"
                    value={rec.month3}
                    onChange={e => handleMonthChange(idx, "month3", e.target.value)}
                  />
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
    </div>
  );
};

export default EditableWaterReport;
